CREATE VIRTUAL TABLE t1 USING fts4(x,y,order=DESC,prefix=2); INSERT INTO t1 VALUES('one two five four five',''),('','one two five four five'),('one two','five four five'); BEGIN; WITH RECURSIVE n(i) AS (VALUES(0) UNION ALL SELECT i+1 FROM n WHERE i<147) INSERT INTO t1(x) SELECT replace(hex(zeroblob(100)),'00','five ') FROM n; INSERT INTO t1(x) VALUES('aaaaaaa fiveaaaaa'); COMMIT; INSERT INTO t1(t1) VALUES('optimize'); UPDATE t1_segments SET block=zeroblob(length(block)) WHERE length(block)>12288;